/* UI orchestration. Storage, auth, permissions, accounting rules and reports live in separate modules. */
(function(){
  'use strict';
  const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],A=()=>OfficeAccounting,P=()=>OfficePermissions,F=()=>OfficeForms;
  const state={user:null,users:[],records:[],audit:[],settings:{...OfficeAccounting.DEFAULT_SETTINGS},view:'dashboard',category:'Rent',categoryAll:'month',categoryQuery:'',month:OfficeAccounting.today().slice(0,7),query:'',editingId:null,reportType:'monthly',confirmResolver:null,resetUserId:null,passwordSetupRequired:false};
  let toastTimer=0;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>A().money(n,state.settings);
  const dateLabel=(d,o)=>A().formatDate(d,o);
  function toast(message,type='success'){const t=document.createElement('div');t.className=`toast ${type}`;t.textContent=message;$('#toastRegion').append(t);setTimeout(()=>t.remove(),3600);}
  function showError(id,message){const e=$(id);e.textContent=message;e.hidden=false;}
  function clearError(id){const e=$(id);e.hidden=true;e.textContent='';}
  function auditEntry(action,record,previousValue,newValue){return {id:A().id(),userId:state.user?.id||null,userName:state.user?.name||'System',role:state.user?.role||'SYSTEM',action,recordId:record?.transactionId||record?.id||null,category:record?.category||'System',previousValue:previousValue??null,newValue:newValue??null,timestamp:new Date().toISOString()};}
  function auditSnapshot(record){if(!record)return null;const copy={...record};delete copy.attachmentData;return copy;}
  async function refreshData(){const [users,records,audit,settings]=await Promise.all([OfficeDB.getAll('users'),OfficeDB.getAll('records'),OfficeDB.getAll('audit'),OfficeDB.getAll('settings')]);state.users=users.map(OfficeAuth.safeUser);state.records=records;state.audit=audit.sort((a,b)=>b.timestamp.localeCompare(a.timestamp));state.settings=settings.find(x=>x.id==='main')||{...A().DEFAULT_SETTINGS};}
  async function requireActiveSession(){if(!state.user)throw new Error('Sign in to continue.');const saved=await OfficeDB.get('users',state.user.id);if(!saved||!saved.active||saved.role!==state.user.role){await OfficeAuth.logout().catch(()=>{});state.user=null;setAuthScreen('login');throw new Error('Your session is no longer active. Sign in again.');}state.user=OfficeAuth.safeUser(saved);return state.user;}
  function setAuthScreen(){ $('#appShell').hidden=true;$('#authScreen').hidden=false;$('#loginCard').hidden=false; }
  function renderCategoryNav(){const root=$('#categoryNav');root.innerHTML=A().CATEGORIES.map(c=>`<button class="category-link ${state.view==='category'&&state.category===c.id?'active':''}" data-category="${esc(c.id)}" type="button"><span class="category-dot"></span>${esc(c.name)}</button>`).join('');}
  function updateProfile(){if(!state.user)return;$('#profileName').textContent=state.user.name;$('#profileRole').textContent=state.user.role==='ADMIN'?'Admin':'Employee';$('#avatar').textContent=(state.user.name||'U').trim().slice(0,1).toUpperCase();$$('.admin-only').forEach(el=>el.hidden=!P().isAdmin(state.user));renderCategoryNav();}
  function showView(view){if(['employees','audit','settings'].includes(view)&&!P().isAdmin(state.user)){toast('Only an Admin can open that section.','error');return;}state.view=view;$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const title=view==='category'?state.category:({dashboard:'Dashboard',ledger:'Accounting ledger',employees:'Employees',reports:'Reports',audit:'Audit history',settings:'Settings'}[view]||view);$('#crumbCurrent').textContent=title;$('#globalSearch').value=state.query;renderCategoryNav();if(view==='dashboard')renderDashboard();if(view==='category')renderCategory();if(view==='ledger')renderLedger();if(view==='employees')renderEmployees();if(view==='reports')renderReports();if(view==='audit')renderAudit();if(view==='settings')renderSettings();closeMobileMenu();}
  function visibleRecords(){return A().cleanRecords(state.records).filter(r=>P().canSee(state.user,r));}
  function recordDescription(r){return r.description||r.subcategory||r.property||r.meterFlat||r.gstType||r.expenseType||r.reason||r.category;}
  function recordPerson(r){return r.category==='Salaries'?r.employeeName:(r.client||r.person||r.vendor||r.payee||'—');}
  function displayStatus(r){return r.status||((r.category==='Refunded Payments')?'Received':'Paid');}
  function statusClass(value){const s=String(value||'').toLowerCase();if(['paid','received','filed','active'].includes(s))return 'paid';if(['pending','requested','draft','partially paid'].includes(s))return 'pending';if(['overdue','inactive','archived'].includes(s))return 'overdue';return '';}
  function badge(s){return `<span class="status ${statusClass(s)}">${esc(s||'Paid')}</span>`;}
  function amountFor(r){return Number(r.amount)||0;}
  function rowActions(r){const canEdit=P().canUpdate(state.user,r);return `<div class="table-actions">${canEdit?`<button class="btn small" data-edit-id="${esc(r.id)}" type="button">Update</button>`:''}${r.category==='Client Expenses'&&A().canRefund(r,state.records)?`<button class="btn small soft" data-refund-original="${esc(r.id)}" type="button">Record refund</button>`:''}${r.attachmentId?`<button class="btn small text" data-attachment="${esc(r.attachmentId)}" type="button">Attachment</button>`:''}${P().canDelete(state.user)?`<button class="btn small danger" data-archive-id="${esc(r.id)}" type="button">Archive</button>`:''}</div>`;}
  function recentRows(records,limit=7){const rows=[...records].sort((a,b)=>(b.updatedAt||b.createdAt||'').localeCompare(a.updatedAt||a.createdAt||'')).slice(0,limit);if(!rows.length)return `<div class="empty-state"><strong>No accounting entries yet</strong>Use “New entry” to record office activity.</div>`;return `<div class="table-scroll"><table><thead><tr><th>Date</th><th>Transaction</th><th>Category</th><th>Entered by</th><th class="money">Amount</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${dateLabel(r.date||r.paymentDate||r.createdAt?.slice(0,10),{month:'short',day:'numeric',year:'2-digit'})}</td><td><span class="td-main">${esc(r.transactionId||'')}</span><span class="td-sub">${esc(recordDescription(r))}</span></td><td>${esc(r.category)}</td><td>${esc(state.users.find(u=>u.id===r.createdBy)?.name||r.createdByName||'—')}</td><td class="money">${money(amountFor(r))}</td><td>${badge(displayStatus(r))}</td></tr>`).join('')}</tbody></table></div>`;}
  function metric(label,value,icon,tone='',kind='money'){const shown=typeof value==='number'?(kind==='count'?new Intl.NumberFormat().format(value):money(value)):esc(value);return `<article class="card metric-card"><div class="metric-top"><span class="metric-label">${esc(label)}</span><span class="metric-icon ${tone}">${icon}</span></div><div class="metric-value">${shown}</div></article>`;}
  function monthControl(){return `<label class="filter-control"><span class="filter-label">Month</span><input id="dashboardMonth" type="month" value="${esc(state.month)}" aria-label="Select reporting month"></label>`;}
  function renderDashboard(){P().isAdmin(state.user)?renderAdminDashboard():renderEmployeeDashboard();}
  function monthBarChart(records){const months=A().lastMonths(6,`${state.month}-15`);const values=months.map(m=>A().monthlySummary(records,m).totalExpenses);const max=Math.max(...values,1);return `<div class="chart-wrap">${months.map((m,i)=>{const height=Math.max(values[i]>0?4:0,Math.round(values[i]/max*100));const label=new Intl.DateTimeFormat(undefined,{month:'short'}).format(new Date(Number(m.slice(0,4)),Number(m.slice(5,7))-1,1));return `<div class="bar-col"><span class="bar-value">${values[i]?esc(money(values[i])):'—'}</span><div class="bar-track"><div class="bar-fill ${i===months.length-1?'current':''}" style="height:${height}%"></div></div><span class="bar-label">${label}</span></div>`;}).join('')}</div>`;}
  function categoryBreakdown(records,month){const data=A().CATEGORIES.map(c=>({name:c.name,total:A().totalForCategory(records,c.id,month)}));const max=Math.max(...data.map(x=>x.total),1);return `<div class="category-breakdown">${data.map(x=>`<div class="breakdown-row"><span class="breakdown-label">${esc(x.name)}</span><span class="breakdown-track"><span class="breakdown-fill" style="display:block;width:${Math.max(x.total?2:0,Math.round(x.total/max*100))}%"></span></span><strong class="breakdown-value">${money(x.total)}</strong></div>`).join('')}</div>`;}
  function renderAdminDashboard(){const records=visibleRecords(),summary=A().monthlySummary(records,state.month),petty=A().pettyBalance(records,state.settings),allOutstanding=A().pendingReimbursements(records);const monthText=new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(new Date(Number(state.month.slice(0,4)),Number(state.month.slice(5,7))-1,1));$('#view-dashboard').innerHTML=`<div class="page-head"><div><div class="eyebrow">FINANCIAL OVERVIEW</div><h1>Good ${greeting()}, ${esc(state.user.name.split(' ')[0])}</h1><p>Here is the office accounting summary for ${esc(monthText)}.</p></div><div class="page-actions">${monthControl()}<button class="btn" data-export="excel" type="button">Export Excel</button><button class="btn" data-print="1" type="button">Print / PDF</button></div></div>
      <div class="grid four">${metric('Total expenses',summary.totalExpenses,'↗')}${metric('Total salaries',summary.byCategory.Salaries||0,'♙','blue')}${metric('Client expenses',summary.clientExpense,'◇','amber')}${metric('Pending client reimbursements',allOutstanding,'◷','red')}</div>
      <div class="section-row"><div><h2>Financial overview</h2><p>Current month totals and live balances</p></div></div>
      <div class="grid four">${metric('Total refunded',summary.refunded,'↶','blue')}${metric('Net office expenses',summary.netOfficeExpenses,'▤')}${metric('Petty cash balance',petty,'₹','amber')}${metric('Pending entries',records.filter(r=>displayStatus(r)==='Pending').length,'◷','red','count')}</div>
      <div class="grid two" style="margin-top:14px"><section class="panel"><div class="panel-head"><div><h2>Expense trend</h2><p>Monthly office expenses · last 6 months</p></div></div>${monthBarChart(records)}</section><section class="panel"><div class="panel-head"><div><h2>Category totals</h2><p>${esc(monthText)} · every category shown separately</p></div></div>${categoryBreakdown(records,state.month)}</section></div>
      <div class="section-row"><div><h2>Recent updates</h2><p>Latest accounting records across the office</p></div><button class="btn text" data-view="ledger" type="button">Open ledger →</button></div><section class="panel">${recentRows(records,8)}</section>`;
    $('#dashboardMonth').addEventListener('change',e=>{state.month=e.target.value||A().today().slice(0,7);renderDashboard();});}
  function greeting(){const h=new Date().getHours();return h<12?'morning':h<18?'afternoon':'evening';}
  function renderEmployeeDashboard(){const records=visibleRecords(),mine=records.filter(r=>r.createdBy===state.user.id||r.updatedBy===state.user.id),today=A().today(),todayRows=mine.filter(r=>A().recordPeriodDate(r)===today),monthRows=mine.filter(r=>A().recordMonth(r)===state.month),pending=mine.filter(r=>displayStatus(r)==='Pending');const shortcuts=A().CATEGORIES.filter(c=>c.id!=='Refunded Payments');$('#view-dashboard').innerHTML=`<div class="page-head"><div><div class="eyebrow">EMPLOYEE WORKSPACE</div><h1>Good ${greeting()}, ${esc(state.user.name.split(' ')[0])}</h1><p>Your accounting activity and entries needing attention.</p></div><div class="page-actions">${monthControl()}<button class="btn" data-print="1" type="button">Print / PDF</button></div></div><div class="grid four">${metric('My entries',mine.length,'▤','','count')}${metric("Today's entries",todayRows.length,'◷','blue','count')}${metric('This month',monthRows.length,'▦','amber','count')}${metric('Pending updates',pending.length,'◷','red','count')}</div><div class="section-row"><div><h2>Accounting categories</h2><p>Open a category to add or update an entry.</p></div></div><div class="category-summary-list">${shortcuts.map(c=>`<button class="category-summary category-shortcut" data-category="${esc(c.id)}" type="button"><span>${esc(c.name)}</span><strong>Open →</strong></button>`).join('')}</div><div class="section-row"><div><h2>Recent updates</h2><p>Your entries and recent shared office activity</p></div><button class="btn text" data-view="ledger" type="button">Open ledger →</button></div><section class="panel">${recentRows(records,8)}</section>`;$('#dashboardMonth').addEventListener('change',e=>{state.month=e.target.value||A().today().slice(0,7);renderDashboard();});}
  function categoryRows(category,records){
    if(category==='Client Expenses')return records.map(r=>{const refunded=A().refundTotalFor(r.id,state.records),out=A().outstandingForClientExpense(r,state.records);return `<tr><td>${dateLabel(r.date,{month:'short',day:'numeric',year:'2-digit'})}</td><td><span class="td-main">${esc(r.transactionId)}</span></td><td>${esc(r.client||'—')}</td><td>${esc(r.project||'—')}</td><td>${esc(r.expenseType||'—')}</td><td class="money">${money(r.amount)}</td><td class="money">${money(refunded)}</td><td class="money">${money(out)}</td><td>${badge(r.reimbursable?(out<=.005?'Reimbursed':refunded?'Partially paid':'Pending'):'Non-reimbursable')}</td><td>${rowActions(r)}</td></tr>`;}).join('');
    if(category==='Refunded Payments')return records.map(r=>{const original=state.records.find(x=>x.id===r.originalRecordId);return `<tr><td>${dateLabel(r.date,{month:'short',day:'numeric',year:'2-digit'})}</td><td><span class="td-main">${esc(r.transactionId)}</span></td><td>${esc(r.client||original?.client||'—')}</td><td>${esc(r.project||original?.project||'—')}</td><td>${esc(original?.transactionId||r.originalTransactionId||'—')}</td><td class="money">${money(r.originalAmount||original?.amount||0)}</td><td class="money">${money(r.amount)}</td><td>${esc(r.paymentMethod||'—')}</td><td>${esc(r.referenceNumber||'—')}</td><td>${rowActions(r)}</td></tr>`;}).join('');
    if(category==='Salaries')return records.map(r=>`<tr><td>${dateLabel(r.paymentDate||r.date,{month:'short',day:'numeric',year:'2-digit'})}</td><td><span class="td-main">${esc(r.transactionId)}</span></td><td>${esc(r.employeeName||'—')}</td><td>${esc(r.salaryMonth||'—')}</td><td class="money">${money(r.grossSalary)}</td><td class="money">${money(r.deductions)}</td><td class="money">${money(r.amount)}</td><td>${badge(displayStatus(r))}</td><td>${rowActions(r)}</td></tr>`).join('');
    if(category==='Petty Cash')return records.map(r=>`<tr><td>${dateLabel(r.date,{month:'short',day:'numeric',year:'2-digit'})}</td><td><span class="td-main">${esc(r.transactionId)}</span></td><td>${esc(r.cashDirection||'Spent')}</td><td>${esc(r.subcategory||'—')}</td><td>${esc(recordDescription(r))}</td><td>${esc(r.person||'—')}</td><td class="money">${r.cashDirection==='Received'?money(r.amount):'—'}</td><td class="money">${r.cashDirection==='Spent'?money(r.amount):'—'}</td><td>${badge(displayStatus(r))}</td><td>${rowActions(r)}</td></tr>`).join('');
    return records.map(r=>`<tr><td>${dateLabel(r.date,{month:'short',day:'numeric',year:'2-digit'})}</td><td><span class="td-main">${esc(r.transactionId)}</span></td><td>${esc(recordDescription(r))}</td><td>${esc(recordPerson(r))}</td><td>${esc(r.subcategory||r.referenceNumber||'—')}</td><td class="money">${money(r.amount)}</td><td>${esc(r.paymentMethod||'—')}</td><td>${badge(displayStatus(r))}</td><td>${rowActions(r)}</td></tr>`).join('');
  }
  function categoryTable(category,records){if(!records.length)return `<div class="empty-state"><strong>No ${esc(category)} entries found</strong>Add an entry or change the month/search filters.</div>`;let heads;if(category==='Client Expenses')heads=['Date','Transaction ID','Client','Project','Expense type','Expense','Refunded','Outstanding','Reimbursement','Actions'];else if(category==='Refunded Payments')heads=['Refund date','Refund ID','Client','Project','Original entry','Original amount','Refund amount','Method','Reference','Actions'];else if(category==='Salaries')heads=['Payment date','Transaction ID','Employee','Salary month','Gross','Deductions','Net paid','Status','Actions'];else if(category==='Petty Cash')heads=['Date','Transaction ID','Direction','Transaction category','Description','Person','Cash received','Cash spent','Status','Actions'];else heads=['Date','Transaction ID','Description','Vendor / person','Reference','Amount','Payment method','Status','Actions'];return `<div class="table-scroll"><table><thead><tr>${heads.map((h,i)=>`<th class="${['Expense','Refunded','Outstanding','Original amount','Refund amount','Gross','Deductions','Net paid','Cash received','Cash spent','Amount'].includes(h)?'money':''}">${h}</th>`).join('')}</tr></thead><tbody>${categoryRows(category,records)}</tbody></table></div>`;}
  function filteredCategoryRecords(category){const all=visibleRecords().filter(r=>r.category===category),q=state.categoryQuery.toLowerCase().trim();return all.filter(r=>(state.categoryAll==='all'||A().recordMonth(r)===state.month)&&(!q||JSON.stringify(r).toLowerCase().includes(q))).sort((a,b)=>(b.date||b.createdAt||'').localeCompare(a.date||a.createdAt||''));}
  function renderCategory(){const category=state.category,meta=A().CATEGORY_MAP[category];if(!meta)return;const all=visibleRecords().filter(r=>r.category===category),rows=filteredCategoryRecords(category),mode=state.categoryAll,q=state.categoryQuery;const total=A().totalForCategory(all,category,state.month);let supplemental='';if(category==='Client Expenses'){const full=visibleRecords();supplemental=`<div class="grid three" style="margin-bottom:13px">${metric('Total client expenses',A().totalClientExpenses(full),'◇')}${metric('Total refunded',A().totalRefunded(full),'↶','blue')}${metric('Outstanding reimbursement',A().pendingReimbursements(full),'◷','amber')}</div>`;}if(category==='Petty Cash'){const p=A().pettyTotals(all);supplemental=`<div class="grid three" style="margin-bottom:13px">${metric('Opening balance',Number(state.settings.openingPettyCash)||0,'₹')}${metric('Cash received',p.received,'↙','blue')}${metric('Cash spent',p.spent,'↗','amber')}</div><div class="callout">Current closing balance: <strong>${money(A().pettyBalance(all,state.settings))}</strong>. The ledger calculates opening balance + cash received − cash spent.</div>`;}
    const addLabel=category==='Refunded Payments'?'＋ Record refund':'＋ Add entry';const newAction=category==='Refunded Payments'?'data-new-refund="1"':`data-add-category="${esc(category)}"`;const extra=category==='Client Expenses'?`<button class="btn soft" data-new-refund="1" type="button">＋ Record client refund</button>`:'';const addButton=P().canCreate(state.user,category)?`<button class="btn primary" ${newAction} type="button">${addLabel}</button>`:'';
    $('#view-category').innerHTML=`<div class="page-head"><div class="category-hero"><div class="category-mark">${esc(meta.icon)}</div><div><div class="eyebrow">ACCOUNTING CATEGORY</div><h1>${esc(category)}</h1><p>Independent records, totals, and report filters for this category.</p></div></div><div class="page-actions"><label class="filter-control"><span class="filter-label">Month</span><input id="categoryMonth" type="month" value="${esc(state.month)}"></label>${extra}${addButton}</div></div>${supplemental}<section class="panel"><div class="panel-head"><div><h2>${esc(category)} entries</h2><p><span id="categoryShownCount">${rows.length} ${rows.length===1?'record':'records'}</span> shown · ${esc(new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(new Date(Number(state.month.slice(0,4)),Number(state.month.slice(5,7))-1,1)))}</p></div><div class="panel-head-actions"><strong class="small-total">${money(total)}</strong></div></div><div class="table-toolbar"><label class="filter-control search-control"><span>⌕</span><input id="categorySearch" type="search" value="${esc(q)}" placeholder="Search this category"></label><label class="filter-control"><span class="filter-label">Period</span><select id="categoryAllTime"><option value="month" ${mode==='month'?'selected':''}>Selected month</option><option value="all" ${mode==='all'?'selected':''}>All time</option></select></label></div><div id="categoryTable">${categoryTable(category,rows)}</div></section>`;
    $('#categoryMonth').addEventListener('change',e=>{state.month=e.target.value||A().today().slice(0,7);renderCategory();});$('#categoryAllTime').addEventListener('change',e=>{state.categoryAll=e.target.value;const r=filteredCategoryRecords(category);$('#categoryShownCount').textContent=`${r.length} ${r.length===1?'record':'records'}`;$('#categoryTable').innerHTML=categoryTable(category,r);});$('#categorySearch').addEventListener('input',e=>{state.categoryQuery=e.target.value;const r=filteredCategoryRecords(category);$('#categoryShownCount').textContent=`${r.length} ${r.length===1?'record':'records'}`;$('#categoryTable').innerHTML=categoryTable(category,r);});
  }
  function ledgerFilters(){return `<div class="page-head"><div><div class="eyebrow">ACCOUNTING</div><h1>Accounting ledger</h1><p>Search and review office transactions from one source of truth.</p></div><div class="page-actions"><button class="btn" data-export="excel" type="button">Export Excel</button><button class="btn" data-print="1" type="button">Print / PDF</button></div></div><section class="panel"><div class="table-toolbar"><label class="filter-control search-control"><span>⌕</span><input id="ledgerSearch" type="search" value="${esc(state.query)}" placeholder="ID, category, person, client, project, vendor, reference…"></label><label class="filter-control"><span class="filter-label">Category</span><select id="ledgerCategory"><option value="">All categories</option>${A().CATEGORIES.map(c=>`<option>${esc(c.id)}</option>`).join('')}</select></label><label class="filter-control"><span class="filter-label">Employee</span><select id="ledgerEmployee"><option value="">Everyone</option>${state.users.filter(u=>u.role==='EMPLOYEE').map(u=>`<option value="${esc(u.id)}">${esc(u.name)}</option>`).join('')}</select></label><label class="filter-control"><span class="filter-label">Payment</span><select id="ledgerMethod"><option value="">Any method</option>${A().PAYMENT_METHODS.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="filter-control"><span class="filter-label">Status</span><select id="ledgerStatus"><option value="">Any status</option><option>Paid</option><option>Pending</option><option>Requested</option><option>Received</option><option>Filed</option></select></label></div><div class="quick-filters"><button class="filter-chip" data-preset="Today">Today</button><button class="filter-chip" data-preset="This week">This week</button><button class="filter-chip" data-preset="This month">This month</button><button class="filter-chip" data-preset="Previous month">Previous month</button><button class="filter-chip active" data-preset="All">All dates</button></div><div class="table-toolbar filter-lower"><label class="filter-control"><span class="filter-label">From</span><input id="ledgerFrom" type="date"></label><label class="filter-control"><span class="filter-label">To</span><input id="ledgerTo" type="date"></label><label class="filter-control"><span class="filter-label">Client</span><input id="ledgerClient" type="search" placeholder="Client name…"></label><label class="filter-control"><span class="filter-label">Project</span><input id="ledgerProject" type="search" placeholder="Project name…"></label><label class="filter-control"><span class="filter-label">Min amount</span><input id="ledgerMin" type="number" min="0" step="0.01" placeholder="0"></label><label class="filter-control"><span class="filter-label">Max amount</span><input id="ledgerMax" type="number" min="0" step="0.01" placeholder="Any"></label>${P().isAdmin(state.user)?'<label class="filter-control check-control"><input id="ledgerArchived" type="checkbox"><span>Include archived</span></label>':''}</div><div class="panel-head"><div><h2>Transaction records</h2><p id="ledgerCount">Showing all visible records</p></div></div><div id="ledgerRows"></div></section>`;bindLedgerFilters();renderLedgerRows();}
  function ledgerRowsTable(rows){if(!rows.length)return `<div class="empty-state"><strong>No matching entries</strong>Try another date range or remove some filters.</div>`;return `<div class="table-scroll"><table><thead><tr><th>Date</th><th>Transaction ID</th><th>Category</th><th>Description</th><th>Employee</th><th>Client / project</th><th class="money">Debit</th><th class="money">Credit</th><th>Payment</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>{const r=x.record;return `<tr><td>${dateLabel(x.date,{month:'short',day:'numeric',year:'2-digit'})}</td><td><span class="td-main">${esc(x.id)}</span>${r.archivedAt?'<span class="td-sub">Archived</span>':''}</td><td>${esc(x.category)}</td><td>${esc(x.description)}${r.referenceNumber?`<span class="td-sub">Ref ${esc(r.referenceNumber)}</span>`:''}</td><td>${esc(x.createdBy)}</td><td>${esc([x.client,x.project].filter(Boolean).join(' · ')||'—')}</td><td class="money">${x.debit?money(x.debit):'—'}</td><td class="money">${x.credit?money(x.credit):'—'}</td><td>${esc(x.paymentMethod)}</td><td>${badge(r.archivedAt?'Archived':x.status)}</td><td>${r.archivedAt?'':rowActions(r)}</td></tr>`;}).join('')}</tbody></table></div>`;}
  function renderLedgerRows(){const q=($('#ledgerSearch')?.value||'').trim().toLowerCase(),cat=$('#ledgerCategory')?.value||'',employee=$('#ledgerEmployee')?.value||'',method=$('#ledgerMethod')?.value||'',status=$('#ledgerStatus')?.value||'',client=($('#ledgerClient')?.value||'').toLowerCase(),project=($('#ledgerProject')?.value||'').toLowerCase(),from=$('#ledgerFrom')?.value||'',to=$('#ledgerTo')?.value||'',min=Number($('#ledgerMin')?.value),max=Number($('#ledgerMax')?.value),includeArchived=$('#ledgerArchived')?.checked||false;const rows=state.records.filter(r=>(includeArchived&&P().isAdmin(state.user)?true:!r.archivedAt)&&P().canSee(state.user,{...r,archivedAt:null})).map(r=>A().buildLedgerRow(r,state.users,state.records)).filter(x=>{const r=x.record,hay=[x.id,x.category,x.description,x.employee,x.client,x.project,x.vendor,x.reference,x.paymentMethod].join(' ').toLowerCase();return (!q||hay.includes(q))&&(!cat||x.category===cat)&&(!employee||r.createdBy===employee)&&(!method||r.paymentMethod===method)&&(!status||x.status===status)&&(!client||x.client.toLowerCase().includes(client))&&(!project||x.project.toLowerCase().includes(project))&&(!from||x.date>=from)&&(!to||x.date<=to)&&(!Number.isFinite(min)||min===0||x.amount>=min)&&(!Number.isFinite(max)||max===0||x.amount<=max);}).sort((a,b)=>b.date.localeCompare(a.date));$('#ledgerCount').textContent=`${rows.length} ${rows.length===1?'record':'records'} · all totals are based on saved entries`;$('#ledgerRows').innerHTML=ledgerRowsTable(rows);}
  function bindLedgerFilters(){['ledgerSearch','ledgerCategory','ledgerEmployee','ledgerMethod','ledgerStatus','ledgerFrom','ledgerTo','ledgerClient','ledgerProject','ledgerMin','ledgerMax','ledgerArchived'].forEach(id=>{const el=$(`#${id}`);if(el)el.addEventListener(el.type==='search'?'input':'change',renderLedgerRows);});$$('[data-preset]').forEach(b=>b.addEventListener('click',()=>{const preset=b.dataset.preset;$$('[data-preset]').forEach(x=>x.classList.toggle('active',x===b));const range=preset==='All'?{from:'',to:''}:A().dateRangeForPreset(preset);$('#ledgerFrom').value=range.from;$('#ledgerTo').value=range.to;renderLedgerRows();}));}
  function renderLedger(){ledgerFilters();}
  function renderEmployees(){P().assertAdmin(state.user,'manage employee accounts');const emps=state.users.filter(u=>u.role==='EMPLOYEE').sort((a,b)=>a.name.localeCompare(b.name));$('#view-employees').innerHTML=`<div class="page-head"><div><div class="eyebrow">ACCESS MANAGEMENT</div><h1>Employees</h1><p>Invite employees and manage their account access. Employee permissions cannot delete accounting entries.</p></div><div class="page-actions"><button class="btn primary" id="addEmployeeBtn" type="button">＋ Invite employee</button></div></div><div class="grid three" style="margin-bottom:14px">${metric('Employee accounts',emps.length,'♙','blue','count')}${metric('Active accounts',emps.filter(u=>u.active).length,'✓','','count')}${metric('Disabled accounts',emps.filter(u=>!u.active).length,'−','amber','count')}</div><section class="panel"><div class="panel-head"><div><h2>Employee access</h2><p>Supabase manages sign-in. Admins can email reset links or disable access.</p></div></div>${emps.length?`<div class="table-scroll"><table><thead><tr><th>Employee</th><th>Email</th><th>Role</th><th>Entries</th><th>Account status</th><th>Created</th><th>Actions</th></tr></thead><tbody>${emps.map(u=>{const count=state.records.filter(r=>r.createdBy===u.id&&!r.archivedAt).length;return `<tr><td><span class="td-main">${esc(u.name)}</span>${u.needsPasswordReset?'<span class="td-sub">Imported account · password reset required</span>':''}</td><td>${esc(u.username)}</td><td>Employee</td><td>${count}</td><td>${badge(u.active?'Active':'Inactive')}</td><td>${dateLabel(u.createdAt?.slice(0,10),{month:'short',day:'numeric',year:'2-digit'})}</td><td><div class="table-actions"><button class="btn small" data-reset-user="${esc(u.id)}" type="button">Send reset email</button><button class="btn small ${u.active?'danger':'soft'}" data-toggle-user="${esc(u.id)}" type="button">${u.active?'Disable':'Activate'}</button></div></td></tr>`;}).join('')}</tbody></table></div>`:`<div class="empty-state"><strong>No employee accounts yet</strong>Add employees so they can sign in and record their entries.</div>`}</section>`;$('#addEmployeeBtn').addEventListener('click',()=>openUserDialog());}
  function openUserDialog(){const f=$('#userForm');f.reset();clearError('#userError');$('#userModalTitle').textContent='Add employee';$('#userDialog').showModal();}
  function reportTypeOptions(){return [['monthly','Monthly report'],['expense','Expense report'],['employee','Employee entry report'],['clients','Client expense report'],['petty','Petty cash report'],['salary','Salary report'],['maintenance','Maintenance report']];}
  function reportCell(value,header){if(typeof value==='number'&&/(amount|total|expense|refund|outstanding|balance|debit|credit|salary|deduction|received|spent|gross|net)/i.test(header))return `<td class="money">${money(value)}</td>`;if(typeof value==='string'&&/^\d{4}-\d\d-\d\d(?:T.*)?$/.test(value))return `<td>${dateLabel(value.slice(0,10),{month:'short',day:'numeric',year:'2-digit'})}</td>`;return `<td>${esc(value)}</td>`;}
  function renderReportTable(data){if(!data.rows.length)return `<div class="empty-state"><strong>No report data for this selection</strong>Try another month, employee, or date range.</div>`;return `<div class="table-scroll"><table><thead><tr>${data.headers.map(h=>`<th class="${/(amount|total|expense|refund|outstanding|balance|debit|credit|salary|deduction|received|spent|gross|net)/i.test(h)?'money':''}">${esc(h)}</th>`).join('')}</tr></thead><tbody>${data.rows.map(row=>`<tr>${row.map((v,i)=>reportCell(v,data.headers[i])).join('')}</tr>`).join('')}</tbody></table></div>`;}
  function renderReports(){const users=P().isAdmin(state.user)?state.users.filter(u=>u.role==='EMPLOYEE'):[];const reportRecords=visibleRecords();const employeeId=P().isAdmin(state.user)?(state.reportEmployee||''):state.user.id;const type=state.reportType;const from=$('#reportFrom')?.value||'',to=$('#reportTo')?.value||'';const data=OfficeReports.report(type,{records:reportRecords,users:state.users,settings:state.settings,month:state.month,employeeId,from,to});const options=reportTypeOptions().filter(([id])=>P().isAdmin(state.user)||id!=='employee');$('#view-reports').innerHTML=`<div class="page-head"><div><div class="eyebrow">REPORTING</div><h1>Reports</h1><p>Category totals and date-based office accounting reports.</p></div><div class="page-actions"><button class="btn" data-export="excel" type="button">Export Excel</button><button class="btn" data-print="1" type="button">Print / PDF</button></div></div><section class="panel"><div class="report-controls"><label>Report<select id="reportType">${options.map(([id,name])=>`<option value="${id}" ${type===id?'selected':''}>${name}</option>`).join('')}</select></label><label>Month<input id="reportMonth" type="month" value="${esc(state.month)}"></label>${P().isAdmin(state.user)?`<label>Employee<select id="reportEmployee"><option value="">Select an employee</option>${users.map(u=>`<option value="${esc(u.id)}" ${state.reportEmployee===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label>`:''}<label>From<input id="reportFrom" type="date" value="${esc(from)}"></label><label>To<input id="reportTo" type="date" value="${esc(to)}"></label><button id="downloadCsvBtn" class="btn" type="button">Download CSV</button></div><div class="panel-head"><div><h2 id="reportTitle">${esc(data.title)}</h2><p>${type==='monthly'?esc(new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(new Date(Number(state.month.slice(0,4)),Number(state.month.slice(5,7))-1,1))):`${data.rows.length} report rows`}</p></div></div><div id="reportTable">${renderReportTable(data)}</div></section>`;
    $('#reportType').addEventListener('change',e=>{state.reportType=e.target.value;renderReports();});$('#reportMonth').addEventListener('change',e=>{state.month=e.target.value||A().today().slice(0,7);renderReports();});if($('#reportEmployee'))$('#reportEmployee').addEventListener('change',e=>{state.reportEmployee=e.target.value;renderReports();});$('#reportFrom').addEventListener('change',renderReports);$('#reportTo').addEventListener('change',renderReports);$('#downloadCsvBtn').addEventListener('click',()=>OfficeReports.exportCSV(data));}
  function renderAudit(){P().assertAdmin(state.user,'view audit history');const q=($('#auditSearch')?.value||'').trim().toLowerCase();const events=state.audit.filter(x=>!q||JSON.stringify(x).toLowerCase().includes(q)).slice(0,500);$('#view-audit').innerHTML=`<div class="page-head"><div><div class="eyebrow">RECORD HISTORY</div><h1>Audit history</h1><p>Transaction changes, archive actions, refunds, employee access, and settings.</p></div><div class="page-actions"><button class="btn" data-export="excel" type="button">Export Excel</button><button class="btn" data-print="1" type="button">Print / PDF</button></div></div><section class="panel"><div class="table-toolbar"><label class="filter-control search-control"><span>⌕</span><input id="auditSearch" type="search" value="${esc(q)}" placeholder="Search user, action, transaction or category"></label></div>${events.length?`<div class="table-scroll"><table><thead><tr><th>Date & time</th><th>User</th><th>Role</th><th>Action</th><th>Transaction ID</th><th>Category</th><th>Previous value</th><th>New value</th></tr></thead><tbody>${events.map(x=>`<tr><td>${dateLabel(x.timestamp?.slice(0,10),{month:'short',day:'numeric',year:'2-digit'})}<span class="td-sub">${esc(x.timestamp?.slice(11,19)||'')}</span></td><td>${esc(x.userName)}</td><td>${esc(x.role)}</td><td>${badge(x.action)}</td><td>${esc(x.recordId||'—')}</td><td>${esc(x.category||'—')}</td><td class="audit-value">${esc(auditText(x.previousValue))}</td><td class="audit-value">${esc(auditText(x.newValue))}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><strong>No audit events found</strong>Accounting and access changes will appear here.</div>`}</section>`;$('#auditSearch').addEventListener('input',e=>{const value=e.target.value,pos=e.target.selectionStart||value.length;renderAudit();const input=$('#auditSearch');input.focus();input.setSelectionRange(pos,pos);});}
  function auditText(value){if(value==null)return '—';let s=typeof value==='string'?value:JSON.stringify(value);return s.length>120?`${s.slice(0,117)}…`:s;}
  function renderSettings(){P().assertAdmin(state.user,'change settings');const currency=state.settings.currency||'INR';$('#view-settings').innerHTML=`<div class="page-head"><div><div class="eyebrow">WORKSPACE CONTROL</div><h1>Settings</h1><p>Set business details, cash opening balance, and backups.</p></div><div class="page-actions"><button class="btn" id="changePasswordBtn" type="button">Change my password</button></div></div><div class="settings-grid"><section class="panel setting-section"><h2>Business settings</h2><p>These settings are used by dashboards and reports.</p><div class="setting-row"><div class="setting-label"><strong>Business / office name</strong><span>Shown in this workspace</span></div><input class="setting-input" id="settingCompany" maxlength="80" value="${esc(state.settings.companyName||'Office')}"></div><div class="setting-row"><div class="setting-label"><strong>Currency</strong><span>Display format for all accounting totals</span></div><select class="setting-input" id="settingCurrency">${['INR','USD','EUR','GBP','AED','SGD','CAD','AUD'].map(c=>`<option ${currency===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="setting-row"><div class="setting-label"><strong>Petty cash opening balance</strong><span>Opening cash before the current ledger entries</span></div><input class="setting-input" id="settingPetty" type="number" min="0" step="0.01" value="${Number(state.settings.openingPettyCash)||0}"></div><div class="page-actions" style="margin-top:11px"><button class="btn primary" id="saveSettingsBtn" type="button">Save settings</button></div></section>
      <section class="panel setting-section"><h2>Data backup & exports</h2><p>Keep a separate backup of records and audit history. Backups never contain password hashes.</p><div class="setting-row"><div class="setting-label"><strong>JSON backup</strong><span>Export workspace data or add new records from a JSON backup</span></div><div class="page-actions"><button class="btn" id="backupJsonBtn" type="button">Export JSON</button><button class="btn" id="importJsonBtn" type="button">Import</button></div></div><div class="setting-row"><div class="setting-label"><strong>Excel workbook</strong><span>Monthly summary, ledger, client expenses, petty cash, salaries, maintenance</span></div><button class="btn" id="settingsExcelBtn" type="button">Export Excel</button></div><div class="setting-row"><div class="setting-label"><strong>Print</strong><span>Print the current screen or save it as PDF</span></div><button class="btn" id="settingsPrintBtn" type="button">Print / PDF</button></div><input id="backupFileInput" type="file" accept="application/json,.json" hidden></section></div>
      <div class="section-row"><div><h2>Access rules</h2><p>Roles enforced before every data change.</p></div></div><section class="panel"><div class="table-scroll"><table class="perm-table"><thead><tr><th>Action</th><th>Admin</th><th>Employee</th></tr></thead><tbody><tr><td>Create non-salary accounting entries</td><td class="perm-yes">Allowed</td><td class="perm-yes">Allowed</td></tr><tr><td>Create salary entries</td><td class="perm-yes">Allowed</td><td class="perm-no">Admin only</td></tr><tr><td>View salary entries</td><td class="perm-yes">All employees</td><td>Own salary only</td></tr><tr><td>Update accounting entries</td><td class="perm-yes">All active entries</td><td>Entries created by self</td></tr><tr><td>Update salary amount</td><td class="perm-yes">Allowed</td><td class="perm-no">Admin only</td></tr><tr><td>Archive / delete records</td><td class="perm-yes">Allowed · retained in history</td><td class="perm-no">Denied by database policy</td></tr><tr><td>Manage employees, settings, audit</td><td class="perm-yes">Allowed</td><td class="perm-no">Admin only</td></tr></tbody></table></div></section>
      <div class="security-note"><strong>Hosted account security</strong><span>Supabase verifies email and password sign-ins. PostgreSQL Row Level Security enforces account permissions for every data request, and employee sessions cannot delete accounting records. The browser holds a session token while you are signed in.</span></div>`;
    $('#saveSettingsBtn').addEventListener('click',saveSettings);$('#changePasswordBtn').addEventListener('click',()=>openPasswordDialog());$('#backupJsonBtn').addEventListener('click',exportBackup);$('#importJsonBtn').addEventListener('click',()=>$('#backupFileInput').click());$('#backupFileInput').addEventListener('change',e=>{const file=e.target.files?.[0];e.target.value='';if(file)importBackup(file);});$('#settingsExcelBtn').addEventListener('click',()=>exportExcel());$('#settingsPrintBtn').addEventListener('click',()=>printCurrent());}
  function fieldHtml(d,value){const val=value??'';const klass=`field${d.full?' full':''}`;if(d.type==='computed')return `<div class="${klass}"><span>${esc(d.label)}</span><div class="computed-field" id="computed-${esc(d.name)}"><span>Calculated automatically</span><strong>${d.name==='netComputed'?money(0):'Choose an original expense'}</strong></div></div>`;let control='';if(d.type==='select'){const opts=(d.options||[]).map(o=>Array.isArray(o)?o:[o,o]);control=`<select name="${esc(d.name)}" ${d.required?'required':''} ${d.disabled?'disabled':''}>${d.required?'':'<option value="">Select…</option>'}${opts.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(val)?'selected':''}>${esc(l)}</option>`).join('')}</select>`;}else if(d.type==='textarea'){control=`<textarea name="${esc(d.name)}" maxlength="${d.maxLength||500}" ${d.required?'required':''}>${esc(val)}</textarea>`;}else if(d.type==='checkbox'){return `<div class="${klass}"><span>${esc(d.label)}</span><label class="checkbox-row"><input name="${esc(d.name)}" type="checkbox" ${val?'checked':''}>${esc(d.help||d.label)}</label></div>`;}else if(d.type==='file'){control=`<input name="${esc(d.name)}" type="file" accept="${esc(d.accept||'*/*')}" aria-label="${esc(d.label)}">${d.help?`<small>${esc(d.help)}</small>`:''}`;}else{const attrs=[d.required?'required':'',d.min!==undefined?`min="${d.min}"`:'',d.step?`step="${d.step}"`:'',d.maxLength?`maxlength="${d.maxLength}"`:'',d.disabled?'disabled':''].filter(Boolean).join(' ');control=`<input name="${esc(d.name)}" type="${esc(d.type)}" value="${esc(val)}" ${attrs} ${d.type==='number'?'inputmode="decimal"':''}>`;}return `<label class="${klass}">${esc(d.label)}${control}</label>`;}
  function openRecord(category,record=null,originalId=''){if(!record&&!P().canCreate(state.user,category)){toast(category==='Salaries'?'Only an Admin can create salary records.':'You do not have permission to add records.','error');return;}if(record)P().assertUpdate(state.user,record);state.category=category;state.editingId=record?.id||null;$('#recordForm').reset();clearError('#recordError');$('#recordModalTitle').textContent=record?`Update ${category} entry`:`New ${category} entry`;$('#recordModalSubtitle').textContent=category==='Refunded Payments'?'Link this reimbursement to the original client expense.':`Add a ${category.toLowerCase()} transaction to the accounting ledger.`;const fields=F().fieldsFor(category,{user:state.user,users:state.users,records:state.records,record,accounting:A(),formatMoney:money});$('#recordFields').innerHTML=fields.map(d=>fieldHtml(d,record?.[d.name]??(d.name==='date'?A().today():d.name==='paymentMethod'?'Bank transfer':d.name==='status'?'Paid':d.name==='cashDirection'?'Spent':d.name==='employeeId'&&state.user.role==='EMPLOYEE'?state.user.id:''))).join('')+(record?.attachmentName?`<div class="field full"><span>Current attachment</span><span class="computed-field">${esc(record.attachmentName)}</span><label class="checkbox-row"><input name="removeAttachment" type="checkbox">Remove attachment</label></div>`:'');$('#recordAuditHint').textContent=record?`Created by ${state.users.find(u=>u.id===record.createdBy)?.name||record.createdByName||'unknown'} · changes are auditable.`:'Created by '+state.user.name+' · changes are saved to audit history.';$('#recordDialog').showModal();if(originalId&&$('[name="originalRecordId"]'))$('[name="originalRecordId"]').value=originalId;updateComputedFields();bindRecordFormFields(fields);}
  function bindRecordFormFields(fields){const gross=$('[name="grossSalary"]'),deductions=$('[name="deductions"]');if(gross&&deductions){const update=()=>{const net=Math.max(0,(Number(gross.value)||0)-(Number(deductions.value)||0));const computed=$('#computed-netComputed');computed.querySelector('span').textContent='Gross salary less deductions';computed.querySelector('strong').textContent=money(net);};gross.addEventListener('input',update);deductions.addEventListener('input',update);update();}const original=$('[name="originalRecordId"]');if(original)original.addEventListener('change',updateComputedFields);}
  function updateComputedFields(){const select=$('[name="originalRecordId"]');if(!select)return;const original=state.records.find(record=>record.id===select.value),target=$('#computed-refundInfo');if(!target)return;const previous=state.editingId?state.records.find(record=>record.id===state.editingId):null;const editCredit=previous?.originalRecordId===original?.id?Number(previous.amount)||0:0;const balance=original?A().outstandingForClientExpense(original,state.records)+editCredit:0;target.querySelector('span').textContent=original?`${original.client} · ${original.project} · original ${money(original.amount)}`:'Select an eligible expense';target.querySelector('strong').textContent=original?`${money(balance)} outstanding`:'—';const amount=$('[name="amount"]');if(amount)amount.max=String(balance.toFixed(2));}
  function formValues(fields){const out={};for(const d of fields){if(d.type==='computed'||d.type==='file')continue;const el=$(`[name="${d.name}"]`);if(!el)continue;if(d.type==='checkbox')out[d.name]=el.checked;else if(d.type==='number')out[d.name]=el.value===''?0:Number(el.value);else out[d.name]=el.value.trim?.()??el.value;}return out;}
  function newTransactionId(){const date=A().today().replaceAll('-','');return `OL-${date}-${Math.random().toString(36).slice(2,7).toUpperCase()}`;}
  async function saveRecord(event){event.preventDefault();clearError('#recordError');const category=state.category,old=state.editingId?state.records.find(r=>r.id===state.editingId):null;try{await requireActiveSession();if(!$('#recordForm').reportValidity())return;if(old)P().assertUpdate(state.user,old);else P().assertCreate(state.user,category);const fields=F().fieldsFor(category,{user:state.user,users:state.users,records:state.records,record:old,accounting:A(),formatMoney:money}),v=formValues(fields);let amount=Number(v.amount)||0;if(category==='Salaries'){if(!v.employeeId)throw new Error('Choose an employee for this salary record.');if(v.deductions>v.grossSalary)throw new Error('Deductions cannot exceed gross salary.');amount=Math.round((v.grossSalary-v.deductions)*100)/100;if(!v.salaryMonth)throw new Error('Choose the salary month.');v.employeeName=state.users.find(u=>u.id===v.employeeId)?.name||old?.employeeName||'';v.paymentDate=v.date||'';v.date=v.date||`${v.salaryMonth}-01`;}
      if(category==='Refunded Payments'){const original=state.records.find(r=>r.id===v.originalRecordId);if(!A().canRefund(original,state.records)&&original?.id!==old?.originalRecordId)throw new Error('Choose an eligible reimbursable client expense.');if(!original||original.archivedAt)throw new Error('The original client expense is unavailable.');const previous=old&&old.originalRecordId===original.id?Number(old.amount)||0:0;const remaining=A().outstandingForClientExpense(original,state.records)+previous;if(amount<=0||amount>remaining+0.005)throw new Error(`Refund amount must be above zero and no more than ${money(remaining)}.`);v.client=original.client;v.project=original.project;v.originalTransactionId=original.transactionId;v.originalAmount=Number(original.amount)||0;v.status='Received';}
      if(category==='Client Expenses'&&old){const refunded=A().refundTotalFor(old.id,state.records);if(amount+0.005<refunded)throw new Error(`Expense amount cannot be lower than the ${money(refunded)} already refunded.`);if(!v.reimbursable&&refunded>0)throw new Error('This expense has refunds. Keep it reimbursable or archive the refund records first.');}
      if(category==='Petty Cash'&&!['Received','Spent'].includes(v.cashDirection))throw new Error('Choose cash received or spent.');
      if(category!=='Refunded Payments'&&(!Number.isFinite(amount)||amount<=0))throw new Error('Enter an amount above zero.');
      if(category==='GST'&&v.taxableAmount<0)throw new Error('Taxable amount cannot be negative.');
      if(!v.status&&category!=='Refunded Payments')v.status='Paid';
      const data={...v,category,amount:Math.round(amount*100)/100};if(category==='Refunded Payments')data.type='refund';else if(category==='Petty Cash')data.type=v.cashDirection==='Received'?'petty-in':'petty-out';else data.type='expense';
      if(old){data.id=old.id;data.transactionId=old.transactionId;data.createdBy=old.createdBy;data.createdByName=old.createdByName;data.createdAt=old.createdAt;data.attachmentId=old.attachmentId;data.attachmentName=old.attachmentName;data.attachmentPath=old.attachmentPath;P().assertEmployeeSalaryUpdate(state.user,old,data);if(state.user.role==='EMPLOYEE'&&old.category==='Refunded Payments'&&old.originalRecordId!==data.originalRecordId)throw new Error('Employees cannot change the original transaction linked to a refund.');}else{data.id=A().id();data.transactionId=newTransactionId();data.createdBy=state.user.id;data.createdByName=state.user.name;data.createdAt=new Date().toISOString();}
      data.updatedBy=state.user.id;data.updatedByName=state.user.name;data.updatedAt=new Date().toISOString();data.archivedAt=null;
      const file=$('[name="attachmentFile"]')?.files?.[0];const remove=$('[name="removeAttachment"]')?.checked;if(remove){data.attachmentId=null;data.attachmentName='';data.attachmentPath=null;}if(file){if(file.size>4*1024*1024)throw new Error('Attachment must be 4 MB or smaller.');const attachment=await OfficeDB.addAttachment({fileName:file.name,mimeType:file.type||'application/octet-stream',blob:file});data.attachmentId=attachment.id;data.attachmentName=attachment.fileName;data.attachmentPath=attachment.path;}
      const action=old?(old.status!==data.status?'Status changed':'Updated'):(category==='Refunded Payments'?'Refund recorded':data.status==='Paid'?'Payment recorded':'Created');const eventLog=auditEntry(action,data,auditSnapshot(old),auditSnapshot(data));await OfficeDB.commit('records',data,eventLog);if(old?.attachmentPath&&old.attachmentPath!==data.attachmentPath)await OfficeDB.deleteAttachmentPath(old.attachmentPath).catch(()=>{});await refreshData();$('#recordDialog').close();state.editingId=null;toast(old?'Entry updated.':'Entry saved.');if(state.view==='category')renderCategory();else if(state.view==='dashboard')renderDashboard();else if(state.view==='ledger')renderLedger();else if(state.view==='reports')renderReports();
    }catch(err){showError('#recordError',err?.message||'Could not save this record.');}}
  async function archiveRecord(id){await requireActiveSession();const record=state.records.find(r=>r.id===id);if(!record)throw new Error('Record not found.');P().assertDelete(state.user);if(record.category==='Client Expenses'&&state.records.some(r=>r.category==='Refunded Payments'&&r.originalRecordId===record.id&&!r.archivedAt))throw new Error('Archive linked refund records before archiving this client expense.');const archived={...record,archivedAt:new Date().toISOString(),archivedBy:state.user.id,updatedBy:state.user.id,updatedByName:state.user.name,updatedAt:new Date().toISOString()};await OfficeDB.commit('records',archived,auditEntry('Deleted',record,auditSnapshot(record),auditSnapshot(archived)));await refreshData();toast('Record archived and retained in audit history.');if(state.view==='category')renderCategory();else if(state.view==='ledger')renderLedger();else renderDashboard();}
  function askConfirm(title,message,accept='Continue'){return new Promise(resolve=>{state.confirmResolver=resolve;$('#confirmTitle').textContent=title;$('#confirmMessage').textContent=message;$('#confirmAccept').textContent=accept;$('#confirmDialog').showModal();});}
  function resolveConfirm(value){$('#confirmDialog').close();if(state.confirmResolver){state.confirmResolver(value);state.confirmResolver=null;}}
  async function saveSettings(){try{await requireActiveSession();P().assertAdmin(state.user,'change workspace settings');const company=$('#settingCompany').value.trim()||'Office',currency=$('#settingCurrency').value,opening=Number($('#settingPetty').value);if(!Number.isFinite(opening)||opening<0)throw new Error('Opening petty cash must be zero or a positive amount.');const next={id:'main',companyName:company,currency,openingPettyCash:Math.round(opening*100)/100,updatedAt:new Date().toISOString(),updatedBy:state.user.id};const previous={companyName:state.settings.companyName,currency:state.settings.currency,openingPettyCash:state.settings.openingPettyCash};await OfficeDB.commitSetting(next,auditEntry('Updated',{category:'Settings',id:'main'},previous,{companyName:company,currency,openingPettyCash:next.openingPettyCash}));await refreshData();toast('Settings saved.');renderSettings();}catch(e){toast(e.message||'Settings could not be saved.','error');}}
  function openPasswordDialog(resetUserId=null,recovery=false){state.resetUserId=resetUserId;state.passwordSetupRequired=recovery;$('#passwordForm').reset();clearError('#passwordError');$('#passwordCurrentRow').hidden=recovery;$('#passwordForm [name="current"]').required=!recovery;$('#passwordModalTitle').textContent=recovery?'Set your OfficeLedger password':'Change password';$('#passwordModalCopy').textContent=recovery?'Choose a password to finish signing in.':'Choose a new password with at least 12 characters.';$('#passwordSaveBtn').textContent=recovery?'Set password':'Update password';$('#passwordDialog').showModal();}
  async function savePassword(event){event.preventDefault();clearError('#passwordError');const next=$('#passwordForm [name="next"]').value;if(next.length<12||next.length>128){showError('#passwordError','Use a password between 12 and 128 characters.');return;}try{await requireActiveSession();state.user=await OfficeAuth.changePassword(state.user,state.passwordSetupRequired?'':$('#passwordForm [name="current"]').value,next);state.passwordSetupRequired=false;state.resetUserId=null;history.replaceState(null,document.title,`${location.pathname}${location.search}`);$('#passwordDialog').close();toast('Password updated.');}catch(e){showError('#passwordError',e.message||'Password could not be updated.');}}
  async function saveEmployee(event){event.preventDefault();clearError('#userError');const f=$('#userForm'),data=new FormData(f),name=String(data.get('name')||'').trim(),email=OfficeAuth.normalizeEmail(data.get('email'));try{OfficeAuth.validateIdentity(name,email);await requireActiveSession();P().assertAdmin(state.user,'invite employees');await OfficeAuth.createEmployee({name,email},state.user);await refreshData();$('#userDialog').close();toast('Employee invitation sent.');renderEmployees();}catch(e){showError('#userError',e.message||'Employee invitation could not be sent.');}}
  async function toggleEmployee(id){try{await requireActiveSession();P().assertAdmin(state.user,'change employee access');const user=state.users.find(u=>u.id===id);if(!user)return;const turnOn=!user.active;const okay=await askConfirm(turnOn?'Activate employee?':'Disable employee?',turnOn?`${user.name} will be able to sign in again.`:`${user.name} will be signed out on their next session check.` ,turnOn?'Activate':'Disable');if(!okay)return;await OfficeAuth.setActive(id,turnOn,state.user);await refreshData();renderEmployees();toast(turnOn?'Employee account activated.':'Employee account disabled.');}catch(e){toast(e.message||'Employee access could not be changed.','error');}}
  async function downloadAttachment(id){try{const item=await OfficeDB.getAttachment(id);if(!item?.blob)throw new Error('Attachment was not found or you do not have access to it.');const url=URL.createObjectURL(item.blob),a=document.createElement('a');a.href=url;a.download=item.fileName||'attachment';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}catch(e){toast(e.message,'error');}}
  function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200);}
  async function blobToDataURL(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error||new Error('Could not read an attachment.'));r.readAsDataURL(blob);});}
  function dataURLToBlob(data){const [meta,raw]=String(data).split(',');if(!meta||!raw)throw new Error('A backup attachment is invalid.');const mime=(meta.match(/data:([^;]+)/)||[])[1]||'application/octet-stream',bin=atob(raw),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);return new Blob([bytes],{type:mime});}
  async function exportBackup(){try{await requireActiveSession();P().assertAdmin(state.user,'export a full backup');const packed=[];for(const record of state.records){if(!record.attachmentId)continue;const item=await OfficeDB.getAttachment(record.attachmentId);if(item?.blob)packed.push({id:item.id,fileName:item.fileName,mimeType:item.blob.type||'application/octet-stream',data:await blobToDataURL(item.blob)});}const bundle={app:'OfficeLedger',schemaVersion:1,exportedAt:new Date().toISOString(),settings:state.settings,users:state.users.map(u=>({id:u.id,name:u.name,email:u.email,role:u.role,active:u.active,createdAt:u.createdAt})),records:state.records,audit:state.audit,attachments:packed};downloadBlob(new Blob([JSON.stringify(bundle,null,2)],{type:'application/json'}),`officeledger-backup-${A().today()}.json`);toast('JSON backup downloaded. Passwords and sessions are never exported.');}catch(e){toast(e.message||'Backup could not be created.','error');}}
  function validBackup(d){if(!d||d.app!=='OfficeLedger'||d.schemaVersion!==1||!Array.isArray(d.records)||!Array.isArray(d.audit)||!Array.isArray(d.users)||!Array.isArray(d.attachments)||!d.settings||typeof d.settings!=='object')return false;const ids=new Set(),txids=new Set(),refunds=new Map();for(const r of d.records){if(!r||typeof r.id!=='string'||ids.has(r.id)||!A().CATEGORY_MAP[r.category]||typeof r.transactionId!=='string'||!r.transactionId||txids.has(r.transactionId)||!Number.isFinite(Number(r.amount))||Number(r.amount)<0)return false;ids.add(r.id);txids.add(r.transactionId);if(r.category==='Refunded Payments'){const source=d.records.find(x=>x.id===r.originalRecordId);if(!source||source.category!=='Client Expenses')return false;if(!r.archivedAt){if(source.archivedAt)return false;refunds.set(source.id,(refunds.get(source.id)||0)+Number(r.amount));}}}for(const [sourceId,total]of refunds){const source=d.records.find(x=>x.id===sourceId);if(total>Number(source.amount)+.005)return false;}if(!Number.isFinite(Number(d.settings.openingPettyCash||0))||Number(d.settings.openingPettyCash||0)<0)return false;return true;}
  async function importBackup(file){try{await requireActiveSession();P().assertAdmin(state.user,'import a backup');const d=JSON.parse(await file.text());if(!validBackup(d))throw new Error('This is not a valid OfficeLedger JSON backup.');const confirmed=await askConfirm('Import backup records?',`This adds new records only. Existing records, settings, and audit history will stay in the shared workspace.`, 'Import backup');if(!confirmed)return;
      const existing=await OfficeDB.getAll('records'),existingIds=new Set(existing.map(r=>r.id)),existingTransactions=new Set(existing.map(r=>r.transactionId));const newRecords=d.records.filter(r=>!existingIds.has(r.id)&&!existingTransactions.has(r.transactionId)),neededFiles=new Set(newRecords.map(r=>r.attachmentId).filter(Boolean));const attachments=new Map();for(const a of d.attachments){if(!neededFiles.has(a.id)||typeof a.data!=='string')continue;const blob=dataURLToBlob(a.data);if(blob.size>4*1024*1024)throw new Error(`Attachment “${a.fileName||''}” is larger than 4 MB.`);const uploaded=await OfficeDB.addAttachment({fileName:a.fileName,mimeType:a.mimeType,blob});attachments.set(a.id,uploaded);}
      const importedRecords=newRecords.map(r=>{const file=attachments.get(r.attachmentId);return {...r,attachmentId:file?.id||null,attachmentName:file?.fileName||'',attachmentPath:file?.path||null};});const result=await OfficeDB.commitBusinessImport(importedRecords,[]);await refreshData();toast(`Imported ${result.imported} new record${result.imported===1?'':'s'}. Existing records, settings, and audit history were kept.`);showView(state.view);
    }catch(e){toast(e.message||'Backup could not be imported.','error');}}
  function exportExcel(){try{OfficeReports.exportExcel({records:visibleRecords(),users:state.users,settings:state.settings,month:state.month});toast('Excel workbook downloaded.');}catch(e){toast(e.message||'Excel export failed.','error');}}
  function printCurrent(){if(!state.user)return;window.print();}
  async function startApplication(user){state.user=OfficeAuth.safeUser(user);await refreshData();$('#authScreen').hidden=true;$('#appShell').hidden=false;updateProfile();showView('dashboard');if(OfficeAuth.isRecoveryOrInvite()){state.passwordSetupRequired=true;openPasswordDialog(null,true);}}
  async function initialize(){try{await OfficeDB.open();const user=await OfficeAuth.restoreSession();if(user){await startApplication(user);return;}setAuthScreen('login');}catch(e){setAuthScreen('login');showError('#loginError',e.message||'Supabase could not be reached. Check the connection and project configuration.');}}
  async function handleLogin(event){event.preventDefault();clearError('#loginError');const f=$('#loginForm'),data=new FormData(f),email=String(data.get('email')||''),password=String(data.get('password')||'');const button=$('button[type="submit"]',f);button.disabled=true;try{const user=await OfficeAuth.login(email,password);f.reset();await startApplication(user);}catch(e){showError('#loginError',e.message||'Sign in failed.');}finally{button.disabled=false;}}
  async function signOut(){try{await OfficeAuth.logout();}catch{}state.user=null;state.records=[];state.users=[];$('#appShell').hidden=true;$('#loginForm').reset();clearError('#loginError');setAuthScreen('login');}
  async function clickHandler(event){const view=event.target.closest('[data-view]');if(view){showView(view.dataset.view);return;}const category=event.target.closest('[data-category]');if(category){state.category=category.dataset.category;state.categoryQuery='';state.categoryAll='month';showView('category');return;}const add=event.target.closest('[data-add-category]');if(add){openRecord(add.dataset.addCategory);return;}const refund=event.target.closest('[data-new-refund]');if(refund){openRecord('Refunded Payments');return;}const refundOriginal=event.target.closest('[data-refund-original]');if(refundOriginal){openRecord('Refunded Payments',null,refundOriginal.dataset.refundOriginal);return;}const edit=event.target.closest('[data-edit-id]');if(edit){const record=state.records.find(r=>r.id===edit.dataset.editId);if(!record)return;try{openRecord(record.category,record);}catch(e){toast(e.message,'error');}return;}const archive=event.target.closest('[data-archive-id]');if(archive){try{P().assertDelete(state.user);const record=state.records.find(r=>r.id===archive.dataset.archiveId);if(!record)return;const okay=await askConfirm('Archive accounting record?',`${record.transactionId} · ${record.category} · ${money(record.amount)}. It will be excluded from totals but retained in history.`,'Archive record');if(okay)await archiveRecord(record.id);}catch(e){toast(e.message||'This record could not be archived.','error');}return;}const reset=event.target.closest('[data-reset-user]');if(reset){try{P().assertAdmin(state.user,'send employee password reset links');await OfficeAuth.resetPassword(reset.dataset.resetUser,state.user);toast('Password reset email sent.');}catch(e){toast(e.message||'Password reset email could not be sent.','error');}return;}const toggle=event.target.closest('[data-toggle-user]');if(toggle){toggleEmployee(toggle.dataset.toggleUser);return;}const attachment=event.target.closest('[data-attachment]');if(attachment){downloadAttachment(attachment.dataset.attachment);return;}const exportButton=event.target.closest('[data-export="excel"]');if(exportButton){exportExcel();return;}const print=event.target.closest('[data-print]');if(print){printCurrent();return;}}
  function bindStaticEvents(){
    $('#loginForm').addEventListener('submit',handleLogin);$('#recordForm').addEventListener('submit',saveRecord);$('#userForm').addEventListener('submit',saveEmployee);$('#passwordForm').addEventListener('submit',savePassword);
    document.addEventListener('click',clickHandler);$$('[data-close]').forEach(b=>b.addEventListener('click',()=>{const dialog=document.getElementById(b.dataset.close);if(dialog?.open)dialog.close();}));
    $('#confirmAccept').addEventListener('click',()=>resolveConfirm(true));$('#confirmCancel').addEventListener('click',()=>resolveConfirm(false));$('#confirmDialog').addEventListener('close',()=>{if(state.confirmResolver){const fn=state.confirmResolver;state.confirmResolver=null;fn(false);}});
    $('#logoutBtn').addEventListener('click',signOut);$('#profileMenuBtn').addEventListener('click',()=>openPasswordDialog());$('#quickAddBtn').addEventListener('click',()=>openRecord(state.category||'Rent'));
    $('#mobileMenu').addEventListener('click',()=>{ $('#sidebar').classList.add('open');$('#mobileShade').classList.add('show');});$('#mobileClose').addEventListener('click',closeMobileMenu);$('#mobileShade').addEventListener('click',closeMobileMenu);
    $('#globalSearch').addEventListener('click',()=>{if(innerWidth<=760)$('#globalSearch').classList.add('expanded');});$('#globalSearch').addEventListener('input',e=>{state.query=e.target.value;if(state.view==='ledger')renderLedgerRows();});$('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){state.query=e.target.value;showView('ledger');$('#ledgerSearch').value=state.query;renderLedgerRows();$('#ledgerSearch').focus();}if(e.key==='Escape')$('#globalSearch').classList.remove('expanded');});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').focus();$('#globalSearch').classList.add('expanded');}});
    $('#recordDialog').addEventListener('close',()=>{state.editingId=null;});$('#userDialog').addEventListener('close',()=>clearError('#userError'));$('#passwordDialog').addEventListener('close',()=>{state.resetUserId=null;$('#passwordCurrentRow').hidden=false;$('#passwordForm [name="current"]').required=true;if(state.passwordSetupRequired){state.passwordSetupRequired=false;signOut();}});
  }
  function closeMobileMenu(){$('#sidebar').classList.remove('open');$('#mobileShade').classList.remove('show');$('#globalSearch').classList.remove('expanded');}
  document.addEventListener('DOMContentLoaded',()=>{bindStaticEvents();initialize();});
})();
